import { useState, useRef, useCallback, useEffect } from 'react';

const API_BASE = 'http://localhost:5001';

const FIELD_LABELS = {
  shoot_height_cm:        'Shoot Height',
  trunk_circumference_cm: 'Trunk Circumference',
  shoot_age_months:       'Shoot Age',
  num_leaves:             'No. of Leaves',
  leaf_color:             'Leaf Colour',
  bark_texture:           'Bark Texture',
  bark_color:             'Bark Colour',
  straightness:           'Straightness',
};

const FIELD_UNITS = {
  shoot_height_cm: 'cm',
  trunk_circumference_cm: 'cm',
  shoot_age_months: 'mo',
  num_leaves: '',
};

const FIELD_ICONS = {
  shoot_height_cm: '📏',
  trunk_circumference_cm: '🌀',
  shoot_age_months: '📅',
  num_leaves: '🍃',
  leaf_color: '🌿',
  bark_texture: '🪵',
  bark_color: '🎨',
  straightness: '📐',
};

const VERDICT_CONFIG = {
  'Ready':        { icon: '✅', gradient: 'linear-gradient(135deg, #1a7a45 0%, #2d9e5f 100%)', label: 'Ready for Harvest', sub: 'Coppice at 6 cm from ground at 45° angle.' },
  'Nearly Ready': { icon: '⏳', gradient: 'linear-gradient(135deg, #7a5a1a 0%, #c49a20 100%)', label: 'Nearly Ready',       sub: 'Check again in 2–3 weeks for optimal harvest.' },
  'Not Ready':    { icon: '🌱', gradient: 'linear-gradient(135deg, #1a3a7a 0%, #2d5faf 100%)', label: 'Not Ready Yet',      sub: 'Shoot needs more time to mature.' },
};

/* ── Inject global CSS ─────────────────────────────────────────────────────── */
const GLOBAL_CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Nunito:wght@300;400;600;700;800&family=Playfair+Display:wght@600;700&display=swap');
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { background: #0d1f14; font-family: 'Nunito', sans-serif; -webkit-font-smoothing: antialiased; }

  @keyframes fadeUp   { from { opacity:0; transform:translateY(22px); } to { opacity:1; transform:translateY(0); } }
  @keyframes fadeIn   { from { opacity:0; } to { opacity:1; } }
  @keyframes spin     { to { transform:rotate(360deg); } }
  @keyframes barGrow  { from { width:0%; } }
  @keyframes shimmer  { 0%{background-position:-200% center;} 100%{background-position:200% center;} }
  @keyframes float    { 0%,100%{transform:translateY(0);} 50%{transform:translateY(-5px);} }
  @keyframes pulseRing {
    0%  { box-shadow: 0 0 0 0 rgba(192,57,43,0.55); }
    70% { box-shadow: 0 0 0 12px rgba(192,57,43,0); }
    100%{ box-shadow: 0 0 0 0 rgba(192,57,43,0); }
  }

  .ch-page { min-height:100vh; background:linear-gradient(160deg,#0d1f14 0%,#071209 100%); color:#e8f5e9; }

  /* ── Hero ── */
  .ch-hero { position:relative; height:210px; overflow:hidden; }
  .ch-hero-bg {
    position:absolute; inset:0;
    background:
      linear-gradient(180deg, rgba(26,58,34,0.98) 0%, rgba(13,31,20,0.92) 100%),
      radial-gradient(ellipse at 15% 60%, rgba(82,183,136,0.22) 0%, transparent 55%),
      radial-gradient(ellipse at 85% 20%, rgba(45,158,95,0.14) 0%, transparent 50%);
  }
  .ch-hero-orbs {
    position:absolute; inset:0; overflow:hidden;
  }
  .ch-hero-orbs::before {
    content:''; position:absolute;
    width:200px; height:200px; border-radius:50%;
    background:radial-gradient(circle, rgba(82,183,136,0.12) 0%, transparent 70%);
    top:-60px; right:-40px;
  }
  .ch-hero-orbs::after {
    content:''; position:absolute;
    width:120px; height:120px; border-radius:50%;
    background:radial-gradient(circle, rgba(45,158,95,0.1) 0%, transparent 70%);
    bottom:10px; left:10px;
  }
  .ch-hero-content {
    position:relative; z-index:2;
    padding:36px 22px 22px;
    display:flex; flex-direction:column; justify-content:flex-end; height:100%;
    animation:fadeUp 0.6s ease both;
  }
  .ch-badge {
    display:inline-flex; align-items:center; gap:5px;
    background:rgba(82,183,136,0.13); border:1px solid rgba(82,183,136,0.28);
    border-radius:20px; padding:3px 11px;
    font-size:0.65rem; font-weight:700; letter-spacing:0.1em; text-transform:uppercase;
    color:#74d9a0; margin-bottom:10px; width:fit-content; backdrop-filter:blur(8px);
  }
  .ch-hero-title {
    font-family:'Playfair Display',Georgia,serif;
    font-size:1.75rem; font-weight:700; color:#fff; line-height:1.2;
    text-shadow:0 2px 16px rgba(0,0,0,0.6);
  }
  .ch-hero-title em { color:#74d9a0; font-style:normal; }
  .ch-hero-sub { font-size:0.72rem; color:rgba(255,255,255,0.42); margin-top:6px; letter-spacing:0.04em; }

  /* ── Stats strip ── */
  .ch-stats {
    display:flex;
    background:rgba(0,0,0,0.25); border-bottom:1px solid rgba(82,183,136,0.1);
    animation:fadeIn 0.5s 0.3s ease both; opacity:0; animation-fill-mode:forwards;
  }
  .ch-stat { flex:1; padding:13px 0; text-align:center; border-right:1px solid rgba(82,183,136,0.08); }
  .ch-stat:last-child { border-right:none; }
  .ch-stat-v { font-size:1.05rem; font-weight:800; color:#74d9a0; }
  .ch-stat-l { font-size:0.6rem; color:rgba(255,255,255,0.38); text-transform:uppercase; letter-spacing:0.07em; margin-top:2px; }

  /* ── Body ── */
  .ch-body { padding:18px 15px 40px; max-width:520px; margin:0 auto; }

  /* ── Card ── */
  .ch-card {
    background:rgba(255,255,255,0.04); border:1px solid rgba(82,183,136,0.11);
    border-radius:20px; backdrop-filter:blur(10px);
    margin-bottom:14px; overflow:hidden;
    animation:fadeUp 0.45s ease both;
  }
  .ch-card-hdr { padding:15px 18px 0; display:flex; align-items:center; gap:10px; }
  .ch-card-ico {
    width:34px; height:34px; border-radius:9px;
    background:rgba(82,183,136,0.13); border:1px solid rgba(82,183,136,0.18);
    display:flex; align-items:center; justify-content:center; font-size:0.95rem;
  }
  .ch-card-ttl { font-size:0.75rem; font-weight:700; color:#74d9a0; text-transform:uppercase; letter-spacing:0.08em; }
  .ch-card-body { padding:14px 18px 18px; }

  /* ── Textarea ── */
  .ch-input-wrap { position:relative; }
  .ch-ta {
    width:100%; min-height:108px;
    background:rgba(255,255,255,0.05); border:1.5px solid rgba(82,183,136,0.18);
    border-radius:13px; padding:13px 52px 13px 14px;
    font-family:'Nunito',sans-serif; font-size:0.93rem; line-height:1.6;
    color:#e8f5e9; resize:none; outline:none;
    transition:border-color 0.2s, background 0.2s;
  }
  .ch-ta::placeholder { color:rgba(232,245,233,0.28); font-size:0.84rem; }
  .ch-ta:focus { border-color:rgba(82,183,136,0.45); background:rgba(255,255,255,0.07); }
  .ch-mic {
    position:absolute; right:11px; bottom:11px;
    width:38px; height:38px; border-radius:50%; border:none; cursor:pointer;
    font-size:1rem; display:flex; align-items:center; justify-content:center;
    transition:all 0.2s;
  }
  .ch-mic.idle  { background:rgba(82,183,136,0.18); border:1px solid rgba(82,183,136,0.28); }
  .ch-mic.rec   { background:#c0392b; animation:pulseRing 1.4s infinite; }
  .ch-hint { display:flex; align-items:center; gap:6px; font-size:0.7rem; color:rgba(255,255,255,0.32); margin-top:7px; padding:0 2px; }
  .ch-hint-dot { width:4px; height:4px; border-radius:50%; background:#74d9a0; opacity:0.55; }

  /* ── Analyze button ── */
  .ch-btn {
    width:100%; padding:15px; margin-top:13px;
    border:none; border-radius:13px;
    font-family:'Nunito',sans-serif; font-size:0.97rem; font-weight:800;
    cursor:pointer; letter-spacing:0.02em;
    display:flex; align-items:center; justify-content:center; gap:8px;
    position:relative; overflow:hidden; transition:all 0.25s;
  }
  .ch-btn.on {
    background:linear-gradient(135deg,#2d6a4f 0%,#52b788 100%);
    color:#fff; box-shadow:0 8px 22px rgba(82,183,136,0.32);
  }
  .ch-btn.on:hover  { transform:translateY(-2px); box-shadow:0 12px 28px rgba(82,183,136,0.42); }
  .ch-btn.on:active { transform:translateY(0); }
  .ch-btn.off { background:rgba(82,183,136,0.09); color:rgba(255,255,255,0.28); cursor:not-allowed; }
  .ch-shimmer {
    position:absolute; inset:0;
    background:linear-gradient(90deg,transparent 0%,rgba(255,255,255,0.14) 50%,transparent 100%);
    background-size:200% 100%; animation:shimmer 1.4s infinite;
  }
  .ch-spinner { width:18px; height:18px; border-radius:50%; border:2px solid rgba(82,183,136,0.25); border-top-color:#52b788; animation:spin 0.7s linear infinite; flex-shrink:0; }

  /* ── Parsed fields ── */
  .ch-grid { display:grid; grid-template-columns:1fr 1fr; gap:9px; }
  .ch-pill {
    background:rgba(82,183,136,0.07); border:1px solid rgba(82,183,136,0.13);
    border-radius:11px; padding:9px 11px; animation:fadeUp 0.3s ease both;
  }
  .ch-pill-lbl { font-size:0.62rem; color:rgba(255,255,255,0.38); text-transform:uppercase; letter-spacing:0.06em; margin-bottom:2px; }
  .ch-pill-val { font-size:0.88rem; font-weight:700; color:#c8f0d8; }

  /* ── Loading ── */
  .ch-loading { display:flex; align-items:center; justify-content:center; gap:9px; padding:18px; font-size:0.82rem; color:rgba(255,255,255,0.45); }

  /* ── Error ── */
  .ch-err {
    background:rgba(192,57,43,0.11); border:1px solid rgba(192,57,43,0.28);
    border-radius:13px; padding:13px 15px; font-size:0.82rem; color:#f1948a;
    margin-bottom:14px; line-height:1.55; animation:fadeUp 0.3s ease;
  }
  .ch-err strong { display:block; margin-bottom:3px; color:#ec7063; }

  /* ── Result banner ── */
  .ch-banner {
    border-radius:20px; padding:18px 20px;
    display:flex; align-items:center; gap:15px;
    margin-bottom:13px; position:relative; overflow:hidden;
    animation:fadeUp 0.4s ease;
  }
  .ch-banner-ico { font-size:2.2rem; flex-shrink:0; animation:float 3s ease-in-out infinite; z-index:1; }
  .ch-banner-txt { z-index:1; }
  .ch-banner-lbl { font-family:'Playfair Display',serif; font-size:1.45rem; color:#fff; font-weight:700; line-height:1.2; }
  .ch-banner-sub { font-size:0.76rem; color:rgba(255,255,255,0.62); margin-top:4px; line-height:1.4; }
  .ch-banner-glow {
    position:absolute; width:140px; height:140px; border-radius:50%;
    filter:blur(50px); opacity:0.35; right:-20px; top:-30px; z-index:0;
  }

  /* ── Confidence ── */
  .ch-conf-row { display:flex; align-items:center; gap:9px; margin-bottom:9px; }
  .ch-conf-lbl { width:110px; font-size:0.76rem; color:rgba(255,255,255,0.52); flex-shrink:0; }
  .ch-conf-track { flex:1; height:5px; background:rgba(255,255,255,0.07); border-radius:5px; overflow:hidden; }
  .ch-conf-fill { height:100%; border-radius:5px; animation:barGrow 0.75s cubic-bezier(0.34,1.56,0.64,1) both; }
  .ch-conf-pct { width:34px; font-size:0.76rem; font-weight:700; color:#c8f0d8; text-align:right; }

  /* ── Reasons ── */
  .ch-reasons { display:flex; flex-direction:column; gap:9px; }
  .ch-reason {
    display:flex; gap:11px; align-items:flex-start;
    background:rgba(82,183,136,0.06); border:1px solid rgba(82,183,136,0.1);
    border-radius:11px; padding:11px 13px; animation:fadeUp 0.4s ease both;
  }
  .ch-reason-dot { width:6px; height:6px; border-radius:50%; background:#52b788; flex-shrink:0; margin-top:6px; box-shadow:0 0 5px rgba(82,183,136,0.55); }
  .ch-reason-txt { font-size:0.82rem; line-height:1.55; color:rgba(232,245,233,0.78); }

  ::-webkit-scrollbar { width:3px; }
  ::-webkit-scrollbar-thumb { background:rgba(82,183,136,0.28); border-radius:3px; }
`;

function useGlobalStyles() {
  useEffect(() => {
    const id = 'ch-styles';
    if (!document.getElementById(id)) {
      const el = document.createElement('style');
      el.id = id; el.textContent = GLOBAL_CSS;
      document.head.appendChild(el);
    }
  }, []);
}

/* ─── Sub-components ──────────────────────────────────────────────────────── */

function ParsedFields({ fields }) {
  const entries = Object.entries(fields).filter(([, v]) => v !== null && v !== undefined);
  if (!entries.length) return null;
  return (
    <div className="ch-card" style={{ animationDelay: '0.1s' }}>
      <div className="ch-card-hdr">
        <div className="ch-card-ico">📋</div>
        <div className="ch-card-ttl">Detected Values</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-grid">
          {entries.map(([k, val], i) => (
            <div className="ch-pill" key={k} style={{ animationDelay: `${i * 0.04}s` }}>
              <div className="ch-pill-lbl">{FIELD_ICONS[k]} {FIELD_LABELS[k] || k}</div>
              <div className="ch-pill-val">{String(val)}{FIELD_UNITS[k] ? ` ${FIELD_UNITS[k]}` : ''}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function ResultCard({ result }) {
  const vc = VERDICT_CONFIG[result.prediction] || VERDICT_CONFIG['Not Ready'];
  const glowColors = { 'Ready': '#52b788', 'Nearly Ready': '#c49a20', 'Not Ready': '#2d5faf' };
  const confBars = [
    { label: 'Ready',        key: 'Ready',        color: '#52b788' },
    { label: 'Nearly Ready', key: 'Nearly Ready', color: '#c49a20' },
    { label: 'Not Ready',    key: 'Not Ready',    color: '#5b9bd5' },
  ];
  return (
    <>
      <div className="ch-banner" style={{ background: vc.gradient }}>
        <div className="ch-banner-glow" style={{ background: glowColors[result.prediction] || '#52b788' }} />
        <div className="ch-banner-ico">{vc.icon}</div>
        <div className="ch-banner-txt">
          <div className="ch-banner-lbl">{vc.label}</div>
          <div className="ch-banner-sub">{vc.sub}</div>
        </div>
      </div>

      <div className="ch-card" style={{ animationDelay: '0.1s' }}>
        <div className="ch-card-hdr"><div className="ch-card-ico">📊</div><div className="ch-card-ttl">Confidence</div></div>
        <div className="ch-card-body">
          {confBars.map(({ label, key, color }) => (
            <div className="ch-conf-row" key={key}>
              <div className="ch-conf-lbl">{label}</div>
              <div className="ch-conf-track">
                <div className="ch-conf-fill" style={{ width: `${result.confidence?.[key] ?? 0}%`, background: color }} />
              </div>
              <div className="ch-conf-pct">{Math.round(result.confidence?.[key] ?? 0)}%</div>
            </div>
          ))}
        </div>
      </div>

      <div className="ch-card" style={{ animationDelay: '0.2s' }}>
        <div className="ch-card-hdr"><div className="ch-card-ico">🔍</div><div className="ch-card-ttl">Why this result?</div></div>
        <div className="ch-card-body">
          <div className="ch-reasons">
            {result.reasons?.map((r, i) => (
              <div className="ch-reason" key={i} style={{ animationDelay: `${i * 0.07}s` }}>
                <div className="ch-reason-dot" />
                <div className="ch-reason-txt">{r}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

/* ─── Main ────────────────────────────────────────────────────────────────── */
export default function CinnamonHarvest() {
  useGlobalStyles();

  const [text, setText]       = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setMsg]   = useState('');
  const [error, setError]     = useState('');
  const [fields, setFields]   = useState(null);
  const [result, setResult]   = useState(null);
  const [recording, setRec]   = useState(false);
  const recRef    = useRef(null);
  const resultRef = useRef(null);

  const toggleVoice = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input not supported. Use Chrome or Edge.'); return; }
    if (recording) { recRef.current?.stop(); setRec(false); return; }
    const rec = new SR();
    rec.lang = 'en-US'; rec.interimResults = true; rec.continuous = true;
    recRef.current = rec;
    const base = text;
    rec.onresult = e => {
      let int = '', fin = base;
      for (const r of e.results) {
        if (r.isFinal) fin += (fin ? ' ' : '') + r[0].transcript;
        else int = r[0].transcript;
      }
      setText(fin + (int ? ' ' + int : ''));
    };
    rec.onerror = () => setRec(false);
    rec.onend   = () => setRec(false);
    rec.start(); setRec(true);
  }, [recording, text]);

  const analyze = useCallback(async () => {
    if (!text.trim()) return;
    setLoading(true); setError(''); setResult(null); setFields(null);
    try {
      setMsg('Reading your description…');
      const pr = await fetch(`${API_BASE}/api/parse`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text }),
      });
      if (!pr.ok) throw new Error(`Parse failed (${pr.status}): ${await pr.text()}`);
      const parsedFields = (await pr.json()).fields;
      setFields(parsedFields);

      setMsg('Running ML model…');
      const rr = await fetch(`${API_BASE}/api/predict`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: parsedFields }),
      });
      if (!rr.ok) throw new Error(`Predict failed (${rr.status}): ${await rr.text()}`);
      setResult(await rr.json()); setMsg('');
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 80);
    } catch (e) {
      setError(e.message); setMsg('');
    } finally {
      setLoading(false);
    }
  }, [text]);

  return (
    <div className="ch-page">

      {/* Hero */}
      <div className="ch-hero">
        <div className="ch-hero-bg" />
        <div className="ch-hero-orbs" />
        <div className="ch-hero-content">
          <div className="ch-badge">🌿 CCGI Certified · ML Powered</div>
          <div className="ch-hero-title">Ceylon <em>Cinnamon</em><br />Harvest Readiness</div>
          <div className="ch-hero-sub">GI Certified · 91% Model Accuracy · 670 Sample Dataset</div>
        </div>
      </div>

      {/* Stats */}
      <div className="ch-stats">
        {[['91%','Accuracy'],['670','Samples'],['8','Features'],['CCGI','Standard']].map(([v,l]) => (
          <div className="ch-stat" key={l}>
            <div className="ch-stat-v">{v}</div>
            <div className="ch-stat-l">{l}</div>
          </div>
        ))}
      </div>

      <div className="ch-body">

        {/* Input */}
        <div className="ch-card" style={{ animationDelay: '0.12s' }}>
          <div className="ch-card-hdr">
            <div className="ch-card-ico">🎙️</div>
            <div className="ch-card-ttl">Describe your shoot</div>
          </div>
          <div className="ch-card-body">
            <div className="ch-input-wrap">
              <textarea
                className="ch-ta"
                value={text}
                onChange={e => setText(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); analyze(); } }}
                placeholder={'Speak or type naturally, e.g.:\n"Height 145 cm, trunk 4 cm, age 20 months, yellowish green leaves, rough and peeling bark, medium brown, 15 leaves, very straight"'}
              />
              <button className={`ch-mic ${recording ? 'rec' : 'idle'}`} onClick={toggleVoice} title={recording ? 'Stop' : 'Speak'}>
                {recording ? '⏹' : '🎤'}
              </button>
            </div>
            <div className="ch-hint">
              <div className="ch-hint-dot" />
              Tap mic to speak · Press Enter to analyze
            </div>
            <button className={`ch-btn ${loading || !text.trim() ? 'off' : 'on'}`} disabled={loading || !text.trim()} onClick={analyze}>
              {loading && <div className="ch-shimmer" />}
              {loading ? <><div className="ch-spinner" /> Analyzing…</> : '🔍  Check Harvest Readiness'}
            </button>
          </div>
        </div>

        {/* Loading */}
        {loading && statusMsg && (
          <div className="ch-loading"><div className="ch-spinner" />{statusMsg}</div>
        )}

        {/* Error */}
        {error && (
          <div className="ch-err">
            <strong>⚠️ Something went wrong</strong>
            {error}
            <div style={{ marginTop: 5, fontSize: '0.72rem', opacity: 0.65 }}>Make sure Flask is running at localhost:5001</div>
          </div>
        )}

        {/* Parsed fields */}
        {fields && <ParsedFields fields={fields} />}

        {/* Result */}
        <div ref={resultRef}>
          {result && <ResultCard result={result} />}
        </div>

      </div>
    </div>
  );
}
